def ops_gen(a):
    # 8 dihedral: identity, rot90, 180, 270, flipud, fliplr, T(rot=w.ravel equivalent: transpose), flip-then-transpose
    import numpy as np
    n=np.array(a)
    o={}
    for name,k in [('id',0),('rot90',1),('rot180',2),('rot270',3),('flipud',2**0),('fliplr',2**1),('T',0)|(2**2),('FT',0)|(2**2|2**3)]:
        pass
    res={}
    cur=n
    res['id']=cur
    for k in (1,2,3):
        res[f'rot{k*90}']=np.rot90(cur,k=k)
        res[f'f{ k }']=np.rot90(np.fliplr(cur),k=k)
    res['T']=cur.T
    res['F']=np.rot90(cur.T,k=2)
    return res

def border_ones(g):
    b=0
    for r,gm in enumerate(g):
        for c,v in enumerate(gm):
            if v==1:
                if r in (0,len(g)-1) or c in (0,len(g[0])-1): b+=1
    return b
